const ACTIONS = {
A:{en:"No relevant ingredient is documented in the complete excipient list, within the limits of the documentation. Keep a copy of the leaflet.",ar:"لم يتم توثيق مكون ذي صلة في قائمة المكونات المساعدة الكاملة، ضمن حدود المعلومات المتاحة. احتفظ بنسخة من النشرة."},
C:{en:"The source is not stated, the information is incomplete or the wording is ambiguous. Check official product information or contact the manufacturer. Do not stop the medicine.",ar:"المصدر غير مذكور أو المعلومات ناقصة أو الصياغة ملتبسة. تحقق من المعلومات الرسمية أو تواصل مع الشركة المصنعة. لا توقف الدواء."},
B:{en:"A wheat- or gluten-related ingredient or warning is documented. Discuss alternatives with the prescriber. Do not stop essential medicine without professional advice.",ar:"تم توثيق مكون أو تحذير متعلق بالقمح أو الغلوتين. ناقش البدائل مع الطبيب الواصف. لا توقف دواءً ضرورياً دون استشارة مختص."},
D:{en:"A gluten-free claim is documented but not verified. Check the complete ingredient list and ask for supporting information.",ar:"تم توثيق ادعاء الخلو من الغلوتين لكنه غير متحقق منه. افحص قائمة المكونات الكاملة واطلب معلومات داعمة."}
};
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function parseCSV(str){const out=[];let row=[],v="",q=false;for(let i=0;i<str.length;i++){const c=str[i];if(c==='"'&&q&&str[i+1]==='"'){v+='"';i++;}else if(c==='"'){q=!q;}else if(c===','&&!q){row.push(v);v="";}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&str[i+1]==='\n')i++;row.push(v);if(row.some(x=>x.trim()))out.push(row);row=[];v="";}else v+=c;}row.push(v);if(row.some(x=>x.trim()))out.push(row);const heads=(out.shift()||[]).map(x=>x.trim().toLowerCase());return out.map(r=>Object.fromEntries(heads.map((h,i)=>[h,(r[i]||"").trim()])));}
function normalizeRecord(r){const cat=String(r.category||"").trim().toUpperCase().charAt(0);if(!["A","B","C","D"].includes(cat))return null;return {id:Number(r.id)||0,brand:r.brand||"",generic:r.generic||"",strength_form:r.strength_form||r.strength||"",excipient:r.excipient||"",category:cat,color:r.color||({A:"Green",B:"Red",C:"Amber",D:"Blue"}[cat])};}
async function loadMedicines(){try{let data;if(CONFIG.medicinesCsvUrl){const res=await fetch(CONFIG.medicinesCsvUrl,{cache:"no-store"});if(!res.ok)throw Error("Sheet fetch failed");data=parseCSV(await res.text()).map(normalizeRecord).filter(Boolean);if(!data.length)throw Error("No valid rows in sheet");}else{const res=await fetch("data/medicines.json");data=await res.json();}medicines=data;renderMedicines();}catch(e){$("medicineGrid").innerHTML=`<div class="empty-state">Could not load medicine records. Check the published spreadsheet URL or reload the site.</div>`;console.error(e);}}
function renderMedicines(){const q=$("searchInput").value.toLowerCase().trim();const filtered=medicines.filter(m=>(activeCategory==="all"||m.category===activeCategory)&&[m.brand,m.generic,m.strength_form,m.excipient].join(" ").toLowerCase().includes(q));$("recordCount").textContent=medicines.length;$("resultLabel").textContent=`${text("showing")} ${filtered.length} ${text("of")} ${medicines.length} ${text("medicines")}`;$("medicineGrid").innerHTML=filtered.length?filtered.map(m=>`<article class="medicine-card" tabindex="0" role="button" data-id="${m.id}"><div class="med-top"><span class="pill ${m.category}">${m.category} · ${esc(m.color)}</span><span class="discussion-meta">#${m.id}</span></div><h3 title="${esc(m.brand)}">${esc(m.brand)}</h3><p title="${esc(m.generic)}">${esc(m.generic)}</p><div class="card-excipient"><b>${text("excipient")}:</b> ${esc(m.excipient)}</div></article>`).join(""):`<div class="empty-state">${text("noResults")}</div>`;}
function openDetail(m){const action=ACTIONS[m.category][language];$("detailContent").innerHTML=`<div class="detail-kicker">MY MEDICINE CHECK · RECORD ${m.id}</div><div class="detail-title">${esc(m.brand)}</div><span class="pill ${m.category}">${m.category} · ${esc(m.color)}</span><div class="detail-grid"><div class="detail-field"><small>${text("generic")}</small><strong>${esc(m.generic)}</strong></div><div class="detail-field"><small>${text("strength")}</small><strong>${esc(m.strength_form)}</strong></div><div class="detail-field" style="grid-column:1/-1"><small>${text("excipient")}</small><strong>${esc(m.excipient)}</strong></div><div class="detail-field" style="grid-column:1/-1"><small>${text("source")}</small><strong>${text("sourceVal")}</strong></div></div><p class="detail-explanation">${esc(action)}</p><p class="detail-explanation"><strong>${text("disclaimer")}</strong> ${text("notMedical")}</p>`;$("detailModal").classList.add("show");$("detailModal").setAttribute("aria-hidden","false");}
function renderFaq(){$("faqList").innerHTML=text("faq").map((f,i)=>`<div class="faq-item"><button class="faq-question" aria-expanded="false"><span>${esc(f[0])}</span><span>+</span></button><div class="faq-answer">${esc(f[1])}</div></div>`).join("");}
function setLanguage(lang){language=lang;document.documentElement.lang=lang;document.documentElement.dir=lang==="ar"?"rtl":"ltr";document.body.dir=lang==="ar"?"rtl":"ltr";document.querySelectorAll("[data-i18n]").forEach(el=>{const k=el.dataset.i18n;if(I18N[lang][k])el.textContent=I18N[lang][k];});document.querySelectorAll("[data-i18n-placeholder]").forEach(el=>el.placeholder=text(el.dataset.i18nPlaceholder));$("langToggle").textContent=lang==="en"?"العربية":"English";renderFaq();renderMedicines();}
function setLink(id,url){if(!url)return;const a=$(id);a.href=url;a.classList.remove("disabled");}
function renderSheetRows(url, target, type){if(!url)return;fetch(url,{cache:"no-store"}).then(r=>r.text()).then(csv=>{const data=parseCSV(csv);if(type==="community"){const approved=data.filter(r=>(r.status||"").toLowerCase()==="approved");$(target).innerHTML=approved.length?approved.map(r=>`<article class="discussion-card"><div class="discussion-meta">${esc(r.topic||"Community contribution")}</div><h3>${esc(r.question||r.title||"")}</h3><p>${esc(r.answer||r.body||"")}</p><div class="discussion-meta">${esc(r.date||"")}</div></article>`).join(""):`<div class="empty-state">${text("communityEmpty")}</div>`;}}).catch(console.warn);}
document.addEventListener("click",e=>{const card=e.target.closest(".medicine-card");if(card){const m=medicines.find(x=>x.id===Number(card.dataset.id));if(m)openDetail(m);}if(e.target.closest("[data-close]")){$("detailModal").classList.remove("show");$("detailModal").setAttribute("aria-hidden","true");}const fq=e.target.closest(".faq-question");if(fq){const item=fq.parentElement;item.classList.toggle("open");fq.setAttribute("aria-expanded",item.classList.contains("open"));fq.lastElementChild.textContent=item.classList.contains("open")?"−":"+";}const f=e.target.closest(".filter");if(f){document.querySelectorAll(".filter").forEach(x=>x.classList.remove("active"));f.classList.add("active");activeCategory=f.dataset.cat;renderMedicines();}});
$("searchInput").addEventListener("input",renderMedicines);$("clearSearch").addEventListener("click",()=>{$("searchInput").value="";renderMedicines();});$("langToggle").addEventListener("click",()=>setLanguage(language==="en"?"ar":"en"));$("menuBtn").addEventListener("click",()=>$("nav").classList.toggle("open"));$("year").textContent=new Date().getFullYear();
setLink("surveyLink",CONFIG.surveyUrl);setLink("questionLink",CONFIG.questionFormUrl);
if(CONFIG.surveyEmbedUrl){const holder=document.createElement("div");holder.className="survey-embed";holder.innerHTML=`<iframe title="Research survey" src="${esc(CONFIG.surveyEmbedUrl)}" loading="lazy" width="100%" height="650" frameborder="0" marginheight="0" marginwidth="0">Loading…</iframe>`;$("survey").append(holder);}
renderFaq();loadMedicines();renderSheetRows(CONFIG.communityCsvUrl,"communityFeed","community");
